quests[26386] = { id = 26386, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Surkhan", description = "Priesterin spricht nicht gut Orcisch, nein.\n\nVielleicht sprecht Ihr mir Surkhan, er ist oben.\n\nSagt ihm, was Ihr in Zul'Gurub gesehen habt, ja.", sourceObjective = "Meldet Euch bei Surkhan in Bambala im Nördlichen Schlingendorntal.", completion = "<Ihr erklärt Surkhan, was sich bisher ereignet hat.>\n\nEs scheint, dass Jin'do überlebt hat und dass er seine Brüder versammelt, um Hakkar erneut in diese Welt beschwören zu können. Es war eine weise Entscheidung, mit mir zu sprechen.\n\nLeider können wir im Moment nicht sehr viel mehr machen als warten und beobachten. Jin'do ist schwach und die Zeit wäre für einen Angriff gut, aber ich muss auf die Reaktion aus Rastakhan warten, bevor ich Befehle erteilen kann. Bis dahin müsst Ihr und Euer Raptor warten.", sourceObjectiveStatus = "unverified-source-field" }
quests[26387] = { id = 26387, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hungerdiät", description = "Die Spinnen, die die Gruselruinen östlich von hier heimsuchen, sind nutzlos. Wir nennen sie zwar Shadrabrut und sie sind auch ganz offensichtlich mit der Spinnengöttin verwandt, aber das ändert auch nichts an der Tatsache, dass sie mehr Ärger machen als Nutzen bringen. Mir wäre es lieber, wenn wir die kleinen Plagegeister einfach ausmerzen könnten.\n\nFalls Ihr Euch zu den Gruselruinen aufmachen solltet, tötet alle Kokons, die Ihr finden könnt. Sie ernähren sich tagelang von den Leichen - die Nahrung der Biester zu zerstören wird effektiver sein, als der Versuch, sie alle zu zerquetschen.", sourceObjective = "Vernichtet 6 eingesponnene Opfer in den Gruselruinen.", completion = "Nun, das ist eine weitaus bessere Situation, von der wir alle etwas haben. Die Spinnen werden entweder verhungern oder sich Zwerge oder Elfen schnappen, um sich zu ernähren. An mir und meinen Kollegen ist ja nichts dran, was ein nahrhaftes Mahl darstellen könnte.", sourceObjectiveStatus = "unverified-source-field" }
quests[26388] = { id = 26388, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwielichthimmel", description = "In Ordnung, Ihr seid also bereit. Wartet hier, bis Kapitän Krazz den Zeppelin gewendet hat und begleitet dann die Luftflotte. Admiral Steinfaust erwartet Euch beim Hafen des Drachenmals!", sourceObjective = "Begleitet die Luftflotte der Horde ins Schattenhochland. Nehmt den Zeppelin vom Turm an der Südlichen Endhaltestelle der Raketenbahn in Azshara.", completion = "Das ist eine Katastrophe, {name}!\n\nUnsere Luftflotte wurde dezimiert. Und wir erhalten Berichte, dass unsere Schiffe grundlos auf offenem Meer von der Allianz angegriffen wurden.\n\nUnd was ist mit Höllschrei? Ist der Kriegshäuptling tot?", sourceObjectiveStatus = "unverified-source-field" }
quests[26389] = { id = 26389, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwarzfelsinvasion", description = "Die Orcs haben begonnen, den Wald niederzubrennen, {name}! Sie haben den Weinberg im Osten übernommen und planen ihren Entscheidungsangriff auf uns! Sie müssen aufgehalten werden!\n\nGeht nach Osten, überquert den Fluss und tötet die wildgewordenen Orcs des Schwarzfelsklans. Sammelt als Beweis ihres Ablebens ihre Waffen ein und kehrt zu mir zurück.\n\nIhr seid unsere einzige Hoffnung, {name}!", sourceObjective = "Bringt 8 Waffen der Orcs des Schwarzfelsklans an Euch.", progress = "Habt Ihr die wildgewordenen Orchorden getötet?", completion = "Die Orcs des Schwarzfelsklans werden jetzt, da ihre Hauptstreitkraft geschlagen wurde, sicherlich fallen. Nun bleibt nur noch eine Aufgabe.", sourceObjectiveStatus = "unverified-source-field" }
quests[26390] = { id = 26390, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Setzt der Invasion ein Ende!", description = "Die wütende Orchorde wird von einem Ungeheuer angeführt, das als Kurtok der Schlächter bekannt ist. Kurtok ist für den vor Kurzem erfolgten Einmarsch verantwortlich und muss getötet werden, wenn wir Frieden im Tal haben wollen.\n\nGeht vorsichtig nach Osten zurück, überquert den Fluss und durchquert den Weinberg. Haltet Ausschau nach der Passage, die in die Berge führt. Dort wird Kurtok sich aufhalten und einen weiteren Angriff vorbereiten. Tötet ihn und kehrt zu mir zurück.", sourceObjective = "Tötet Kurtok den Schlächter.", completion = "Jetzt, da Kurtok tot ist, sind wir wieder vor den orcischen Horden sicher. Ich werde Arbeiter zum Pass entsenden und versuchen, die Passage zu verschließen, damit dort keine Orcs mehr hindurch und auf unser Gebiet gelangen können.\n\nIhr habt den Dank von Sturmwind und der Allianz, Held.", sourceObjectiveStatus = "unverified-source-field" }
quests[26391] = { id = 26391, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hoffnung ersticken", description = "Tage wie diese lassen mich die Zeiten zurücksehnen, in denen die Defias noch da waren. Der Kataklysmus hat einen Weg aus der Brennenden Steppe geöffnet, und jetzt überlaufen Schwarzfelsorcs das Nordhaintal! Sie haben mein Weingut übernommen und brennen es nieder! SIE BRENNEN ES NIEDER!\n\nBitte, {name}, dieses Weingut ist alles, was ich habe. Nehmt meinen Feuerlöscher und löscht die Flammen im Weingut. Vielleicht besteht noch Hoffnung für dieses Land!", sourceObjective = "Benutzt Millys Feuerlöscher, um 8 Brände im Weingut zu löschen.", progress = "Habt Ihr die Feuer gelöscht?", completion = "Seid gesegnet, {name}. Ihr seid ein wahrer Held der Allianz! Auch wenn dieses Land völlig verbrannt und nichts als Schutt und Asche vom Weingut übrig ist, kann es sich vielleicht erholen. Stimmt's? Wie schlimm kann es schon sein?", sourceObjectiveStatus = "unverified-source-field" }
quests[26392] = { id = 26392, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tapferkeitsbelobigung", description = "Ihr habt die Schwarzfelsorcs vertrieben, und dafür sind wir Euch sehr dankbar! Obwohl die Weinberge bis auf den Grund niedergebrannt sind, ist der Rest Nordhains dank Euch sicher.\n\nBitte nehmt diese Belobigung an, die Euren außergewöhnlichen Mut würdigt, und bringt Sie zu Marschall McBride. Er ist für die Sicherheit Nordhains verantwortlich und wird sich freuen, von Euren Taten zu hören.", sourceObjective = "Bringt die Tapferkeitsbelobigung zu Marschall McBride im Nordhaintal im Wald von Elwynn.", sourceObjectiveStatus = "unverified-source-field" }
quests[26393] = { id = 26393, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine eilige Nachricht", description = "Wir bekommen zwar nicht viel Unterstützung von Sturmwind direkt, aber ich habe einen Kontaktmann in der Stadt, der uns mit Rüstungen versorgt. Sein Name ist Osric Strang. Sein Geschäft, Begrenzte Immunität, liegt in der Altstadt von Sturmwind.\n\nUnser Vorrat an Rüstung schwindet, ich muss bei Osric mehr bestellen. Könnt Ihr ihm diese Notiz bringen?\n\nDer schnellste Weg nach Sturmwind führt über Bartlett den Tapferen, unseren Greifenmeister. Er ist direkt bei der Schmiede; bringt ihm meine Notiz und nehmt dann einen Greifen nach Sturmwind.", sourceObjective = "Bringt Argus' Notiz zu Bartlett dem Tapferen, dem Greifenmeister.", progress = "Ihr seht aus, als hättet Ihr es eilig. Tja, dann seid Ihr hier genau richtig!", completion = "Ihr müsst diese Notiz nach Sturmwind bringen? Das ist kein Problem, Ihr könnt einen meiner Greifen nehmen!", sourceObjectiveStatus = "unverified-source-field" }
quests[26394] = { id = 26394, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weiter nach Sturmwind", description = "Gegen eine geringe Gebühr könnt Ihr einen Greifen nach Sturmwind nehmen und so Argus' Notiz zu Osric bringen. Einen schnelleren Weg gibt es nicht.\n\nWenn Euch das akzeptabel erscheint, sprecht mich wieder an, sobald Ihr bereit seid für den Flug. Das kostet eine Kleinigkeit, aber glaubt mir, es lohnt sich!", sourceObjective = "Bucht einen Greifenritt bei Greifenmeister Bartlett dem Tapferen, dann bringt Argus' Notiz zu Osric Strang, im Laden Begrenzte Immunität, in der Altstadt von Sturmwind.", progress = "Ihr seid gereist, ja? Seid Ihr an irgendwelchen interessanten Orten gewesen?", completion = "Ah, eine Notiz von Schmied Argus? Es überrascht mich gar nicht, dass er mehr Ausrüstung braucht. Heutzutage gibt es so viele neue Rekruten.\n\nIch danke Euch, {name}. Hier habt Ihr etwas Geld für Eure Reisespesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26395] = { id = 26395, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dungar Trinkfest", description = "{name}, ich habe alles, worum Argus gebeten hat, in diese Kiste gepackt. Würdet Ihr sie ihm bringen?\n\nWenn Ihr bereits mit Bartlett in Goldhain gesprochen habt, dann könnt Ihr einen Greifen zurück zu ihm nehmen. Dungar Trinkfest ist unser Greifenmeister drüben im Handelsdistrikt.\n\nSprecht mit Dungar, dann bringt diese Kiste auf dem schnellsten Weg zu Argus. Wir möchten nicht, dass unsere kämpfenden Männer und Frauen in Goldhain ohne neue Ausrüstung sind!", sourceObjective = "Bringt Osrics Kiste zu Dungar Trinkfest, dem Greifenmeister.", progress = "Ist das Schweiß auf Eurer Stirn, der Herr? Ihr habt Euch beim Laufen zu sehr verausgabt. Nehmt nächstes Mal einen Greifen!", completion = "Eine Kiste für Goldhain, eh? Seid Ihr schon mal in Goldhain gewesen? Falls ja, ist das kein Problem. Ich habe viele Greifen ausgebildet, damit sie diese Route fliegen können!", sourceObjectiveStatus = "unverified-source-field" }
quests[26396] = { id = 26396, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Argus", description = "Der Name des Greifenmeisters in Goldhain ist Bartlett. Wenn Ihr bereits mit ihm gesprochen habt, könnt Ihr auf einem meiner Greifen zu ihm fliegen.\n\nVergesst nicht: Greifen sind so ausgebildet, dass sie jederzeit in ihre Hauptstadt fliegen können, bringen Euch aber nur zu anderen Greifenmeistern, wenn Ihr schon einmal dort wart.\n\nIhr habt Euch schon einmal mit Bartlett unterhalten, daher sprecht mich einfach erneut an, wenn Ihr auf einem Greifen nach Goldhain fliegen wollt. Sobald Ihr da seid, könnt Ihr Osrics Kiste zu Schmied Argus bringen.", sourceObjective = "Bucht einen Greifenritt nach Goldhain bei Greifenmeister Dungar Trinkfest, dann bringt Osrics Kiste zu Schmied Argus in Goldhain.", progress = "Ihr seid zurück aus Sturmwind? Hat Osric die Rüstungen geschickt?", completion = "Wunderbar, Ihr habt die Rüstungen gebracht! Wir werden sie sofort unter denen verteilen, die sie brauchen.\n\nVielen Dank, {name}. Ihr wart uns wirklich eine große Hilfe. Und jetzt, da Ihr Euch ein wenig mit den Greifen vertraut gemacht habt, hoffe ich, dass Ihr öfter kommt und Goldhain unterstützt!", sourceObjectiveStatus = "unverified-source-field" }
quests[26397] = { id = 26397, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geht mit der Erdenmutter", description = "Vieles hat sich außerhalb von Mulgore geändert, {name}. Die Welt ist zerrissen und unsere Verbündeten der Horde haben dunkle Wege eingeschlagen. Wir müssen sie leiten. Auch in unserer finstersten Stunde werden wir tapfer die Erdenmutter hocherhobenen Haupts bei allem, was wir tun, ehren.\n\nIhr müsst gehen, {name}, und als Vorbild dienen. Geht nach Orgrimmar. Erzählt Saurfang, wie die Grimmtotems vertrieben wurden. Verdeutlicht ihm unseren Stolz und unsere Disziplin, unsere Stärke und unsere Trauer.\n\nTal beim Himmelsturm wird Euch auf den richtigen Weg bringen. Geht in Frieden und vergesst unser Volk nicht.", sourceObjective = "Bringt das Mal von Bluthuf zu Hochfürst Saurfang, der sich in der Feste Grommash in Orgrimmar befindet.\n\nFür die Reise dorthin könnt Ihr mit Tal, dem Windreitermeister, sprechen oder auf den Zeppelin warten.", progress = "Was bringt Euch zu mir, {class}?", completion = "Wollt Ihr mir sagen, dass die Grimmtotems aus Mulgore vertrieben wurden? Ihr müsst ein unerschütterlicher Krieger sein, um Lob von Baine Bluthuf zu bekommen. Die Horde braucht Helden, besonders solche, die Ehre im Herzen tragen. Also schön, {class}. Ich akzeptiere Euch als einen von uns.\n\nFür die Horde!", sourceObjectiveStatus = "unverified-source-field" }
quests[26398] = { id = 26398, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geht mit der Erdenmutter", description = "Ihr habt tapfer an meiner Seite gekämpft, {name}, und viel für mein Volk getan. Wenn doch nur <jeder/jede:r> {race} so edelmütig wäre, würde mir die Zukunft der Horde nicht solches Kopfzerbrechen bereiten.\n\nIch möchte Euch bitten, meine Sorgen ein wenig zu lindern. Geht nach Orgrimmar. Erzählt Hochfürst Saurfang, wie die Grimmtotems vertrieben wurden. Verdeutlicht ihm unseren Stolz und unsere Disziplin, unsere Stärke und unsere Trauer.\n\nTal beim Himmelsturm wird Euch auf den richtigen Weg bringen. Geht in Frieden, <mein Freund/meine Freundin>.", sourceObjective = "Bringt das Mal von Bluthuf zu Hochfürst Saurfang, der sich in der Feste Grommash in Orgrimmar befindet.\n\nFür die Reise dorthin könnt Ihr mit Tal, dem Windreitermeister, sprechen oder auf den Zeppelin warten.", sourceObjectiveStatus = "unverified-source-field" }
quests[26399] = { id = 26399, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schatzkiste der Mosh'Ogg", description = "Sagt, habt Ihr von den Ogern gehört? Ich hab' 'nen heißen Tipp von 'nem Typen namens Mok'thardin bekommen, dass so <'n schwachköpfiger/'ne schwachköpfige:r> {race}, lächerlich angezogen wie <ein/eine:c> {class}, 'ne Ogerhand gefunden hat und...\n\n<Skeezy bricht ab und mustert Euch.>\n\nWas sagte ich gerade? Ach ja... <ein SCHWERTSCHWINGENDER HELD/eine ATEMBERAUBENDE HELDIN> fand diese Ogerhand und Mok'thardin glaubt deswegen, dass die Oger ein besonderes Artefakt haben. Ich habe gesehen, dass sie eine Kiste in den Ruinen hinter ihrem Hügel bewachen. Habt Ihr Lust, sie für mich zu holen?", sourceObjective = "Holt die Belohnung der Mosh'Ogg aus den Ruinen hinter dem Ogerhügel der Mosh'Ogg.", progress = "Wie kommt es, dass ausgerechnet OGER immer die unbezahlbaren Artefakte finden?", completion = "<Skeezy müht sich vergebens ab, den Kasten zu öffnen.>\n\nDiese Oger wissen wirklich, wie man eine Schatztruhe verschließt. Ich sag' Euch 'was... Ein Kasten bringt mir nichts, Held. Wir müssen einen Weg in diese Kiste hinein finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[26400] = { id = 26400, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Universalschlüssel", description = "Wir brauchen etwas Stärkeres als Eure fleischigen Hände, um das hier zu öffnen. Und die Trottel der Venture Company im Nordwesten haben möglicherweise genau das Richtige.\n\nDas letzte Mal, als ich da drüben war, sah ich Schredder herumlaufen, die riesige, rotierende Klingen an den Händen hatten. Das wäre eine Möglichkeit, einen Kasten zu öffnen.\n\nWenn Ihr keine Schredder findet, könnt Ihr auch die riesige Sägeklinge in ihrem Sägewerk am See ausprobieren.", sourceObjective = "Öffnet die Belohnung der Mosh'Ogg, indem Ihr gegen einen Schredder der Venture Co. kämpft, oder die Sägeklinge im Sägewerk der Venture Company benutzt.", progress = "Habt Ihr die Kiste schon geöffnet? Ich kann es kaum erwarten, zu sehen, was sich darin befindet.", completion = "<Der Goblin späht hinein.>\n\nWaaaaaaaa...?!?\n\nIch... Ich muss das zu... zu Flem... im Süden schicken. Er wird etwas damit anzufangen wissen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26401] = { id = 26401, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Vestia", description = "Das sanfte Leuchten des Podests wird stärker. Ihr seht eine schlichte Kette, die zurückgelassen wurde. War es das, wonach der Lehrling gesucht hatte?", sourceObjective = "Bringt das Graunebelamulett zu Vestia Mondspeer im Turm von Estulan.", progress = "Ihr seid zurück… ohne ihn….", completion = "Wie schrecklich, dass jemand so voller Jugend und Talent den Dämonen zum Opfer fallen musste!\n\nBitte, verzeiht mir, dass ich auch Euch in Gefahr gebracht habe, {name}. Ich hoffe, dass Ihr dieser Dämonin nie wieder begegnen müsst…", sourceObjectiveStatus = "unverified-source-field" }
quests[26402] = { id = 26402, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Generalin Shandris Mondfeder", description = "Wir Druiden haben nicht besonders viel mit den Schildwachen zu tun, aber wir arbeiten bereitwillig zusammen, um unser Land zu verteidigen. Jetzt, da Ihr mir geholfen habt, wäre es äußerst nachlässig, wenn ich Euch nicht bitten würde, auch ihnen zu helfen.\n\nShandris Mondfeder, Generalin der Schildwachen, hat den Oberbefehl über alle militärischen Vorgänge in Kalimdor. Sie hält sich in der neu errichteten Mondfederfeste im Süden auf. Sagt Ihr, dass ich Euch schicke. Ich bin mir sicher, dass sie Eure Fähigkeiten benötigt.", sourceObjective = "Sprecht mit Shandris Mondfeder in der Mondfederfeste in Feralas.", completion = "Telaron hat mir bereits von Euch berichtet, {name}. Ich bin gespannt, ob Ihr nur halb so talentiert seid, wie er behauptet.\n\nIch kämpfe einen Krieg an mehreren Fronten und kümmere mich gleichzeitig darum, dass unsere Gebiete richtig verteidigt und unsere jüngsten Schildwachen richtig ausgebildet werden. Wenn Ihr ein geschickter Kämpfer seid, habe ich genug für Euch zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[26403] = { id = 26403, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Minenoperation der Venture Company", description = "Mann, ich hasse die Venture Company. Sie haben eine ganze Reihe von Operationen überall im Schlingendorntal, die hart arbeitende Goblins wie mich davon abhalten, ehrliches Gold zu verdienen!\n\nWie ich das mache? Durch Diebstahl. Die Geologen der Venture Co. in der Nähe des Nazferitisees im Nordwesten sind sehr an diesen merkwürdigen blauen Kristallen interessiert, die sie in den Minen finden. Bringt mir Proben dieses Gesteins von ihren Geologen. Mir ist egal, was Ihr tun müsst, um sie zu erhalten.", sourceObjective = "Bringt 5 gerommelte Kristalle zu Skeezy Whillzap in Bambala im Nördlichen Schlingendorntal.", progress = "Habt Ihr die Kristalle? Ich brauche sie!!\n\nIch meine... ich muss wissen, dass die böse Venture Company im Schlingendorntal an Boden verliert. Denn wisst Ihr, wir ehrlichen Leute müssen unseren Lebensunterhalt verdienen!", completion = "Großartig! Wunderbar! Die werden mir einiges einbringen!!\n\nDiese Venture Company hat sich den falschen Dschungel zum Schürfen ausgesucht, nicht wahr? Es würde uns allen besser gehen, wenn sie hier verschwinden.", sourceObjectiveStatus = "unverified-source-field" }
quests[26404] = { id = 26404, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Höhere Lohngruppe", description = "Hey, seid Ihr schon in Hartzangs Versteck gewesen? Oh, das MÜSST Ihr sehen. Alles, was ein Goblin sich je erträumen kann!\n\nIch sag Euch was... Ihr seht aus, wie <ein überzeugter/eine überzeugte:c> {class}. Raskha da drüben, der in Weste und Rock, kann Euch einen Flug verschaffen, falls Ihr den Weg nicht bereits kennt.\n\nGeht auf mich.", sourceObjective = "Sucht Sassy Hartzang in Hartzangs Versteck am Schlingendornkap auf.", completion = "Skeezy hat Euch an den richtigen Ort geschickt. Willkommen in Hartzangs Versteck!", sourceObjectiveStatus = "unverified-source-field" }
quests[26405] = { id = 26405, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mambo in Zul'Mamwe", description = "Die Schädelspalter sind eine Schande für das ganze Trollreich. Ihre kindischen Zankereien mit den Blutskalpen haben das Nördliche Schlingendorntal zerrissen. Während Stämme wie die Dunkelspeere und die Zandalari erblühen, kämpfen die Schädelspalter um Ruinen.\n\nIch wurde ermächtigt, allen Söldnern eine Belohnung zu bezahlen, die bereit sind, den Schädelspaltern eine Lektion zu erteilen. Ich ermutige daher Euch und alle, die Ihr kennt, nach Zul'Mamwe im Süden zu reisen und ihrem abtrünnigen Stamm ein Ende zu setzen.", sourceObjective = "Tötet 16 Trolle der Schädelspalter in Zul'Mamwe.", completion = "Hier ist Eure Belohnung, wie versprochen. Ihr erfüllt das Volk der Trolle mit Stolz.", sourceObjectiveStatus = "unverified-source-field" }
quests[26406] = { id = 26406, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Fangzahn von Shadra", description = "Als Nächstes brauchen wir den Fangzahn von Shadra.\n\nShadras eigene Brut bewacht ihn in den Gruselruinen im Osten. Ihr Gift ist stark, {name}... werdet nicht unvorsichtig.", sourceObjective = "Besorgt den Fangzahn von Shadra aus den Gruselruinen.", progress = "Habt Ihr den Fangzahn?", completion = "Da ist er... nur noch einer übrig.", sourceObjectiveStatus = "unverified-source-field" }
quests[26407] = { id = 26407, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Handschrift von Mosh'Ogg", description = "Dieser Oger hatte einen ungewöhnlichen Gegenstand bei sich: die abgetrennte Hand eines anderen Ogers, die er an einer Schnur befestigt um den Hals trug Die Hand selbst weist viele Narben auf, die in einem schwachen lila leuchten.\n\nEine Narbe, die nach dem Tod leuchtet, ist höchst ungewöhnlich. So einen Gegenstand bei einem Oger zu finden, ist noch merkwürdiger. Vielleicht weiß jemand in Grom'gol etwas mit dieser Kuriosität anzufangen.", sourceObjective = "Bringt die entstellte Hand eines Mosh'Ogg zu Scharfseher Mok'thardin im Basislager Grom'gol im Nördlichen Schlingendorntal.", progress = "Eine Hand sagt Ihr?", completion = "<Der Scharfseher achtet darauf, dass er den Gegenstand an der Schnur hält und vermeidet sorgfältig, die Faust des toten Ogers zu berühren.>\n\nDas ist in der Tat merkwürdig. Ich werde das meinen Kontakten im Osten, in der Nähe des Hauptlagers der Mosh'Ogg, unterbreiten. Ich habe so ein Gefühl, als ob sie sich für diese seltsamen Narben interessieren könnten.\n\nIch danke Euch, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26408] = { id = 26408, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Asche im Eschental", description = "Die Dunkelküste mag zerschlagen und zerschmettert sein, aber dank Euch haben wir hier ein gewisses Maß an Sicherheit erlangt. Ein gewisses Maß an Frieden. Wir müssen noch viel wieder aufbauen.\n\nIhr solltet weitermachen, <mein Freund/meine Liebe>. Garrosh hat die geballte Macht seiner Horde gegen uns im Eschental aufgefahren. Sie werden uns alle töten und den Wald roden, wenn wir nicht gegen sie vorgehen.\n\nUm Hoffnung zu bewahren, diese Wälder nicht vollständig aufgeben zu müssen, benötigen wir Eure Hilfe. Folgt der Straße in Richtung Süden und sucht Schildwache Shyela auf.", sourceObjective = "Sprecht mit Schildwache Shyela bei Orendils Zuflucht im Eschental.", completion = "Schön, ein neues Gesicht in dieser Gegend zu sehen!\n\nDie Horde kriecht überall in den Wäldern herum, aber mein Auftrag sieht vor, dass ich diesen Außenposten absichere. Ich könnte wirklich jemanden gebrauchen, der ein wenig Kampflust mitbringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26409] = { id = 26409, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo ist Goldmine?", description = "Mein goblinischer Initiand ist schon eine ganze Weile fort. Sein Name ist Goldmine.\n\nIch habe ihn losgeschickt, um die Felsklauen im Südwesten im Quarzitbecken zu beobachten. Wärt Ihr bereit, ihn zu suchen? Wenn Ihr ihn findet, bittet ihn, zum Tempel zurückzukommen.", sourceObjective = "Findet Initiand Goldmine am Quarzitbecken in Tiefenheim.", completion = "Hallöchen! Könnt Ihr mir vielleicht kurz helfen, Spezi?", sourceObjectiveStatus = "unverified-source-field" }
quests[26410] = { id = 26410, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Explosive Verbundmasse", description = "Dieser Kerl ist der Sohn des Anführers der Irdenen! Er hatte es schon fast zurück in den Tempel geschafft, als er von mehr Felsklauen angegriffen wurde, als ich zählen konnte!\n\nWir wissen, dass der Steinvater der Irdenen das mittlere Fragment der Weltensäule besitzt. Wenn wir seinen Sohn heilen, gibt er uns vielleicht das Fragment.\n\nMeine Heilzauber funktionieren bei Flint hier nicht. Aber wenn wir an etwas Quarzitharz von diesen Monstern kommen könnten, könnte ich eine explosive Verbundmasse herstellen, die seine Wunden schließt und kauterisiert.", sourceObjective = "Sammelt 5 Einheiten Quarzitharz.", progress = "Ich brauche nicht viel Harz. Diese Felsklauen sind jedoch ziemlich gefährlich.", completion = "Was für ein Glück, dass ich zufällig Großmeister der explosiven Alchemie bin.\n\nDas hier wird sich aber nicht von allein entzünden.", sourceObjectiveStatus = "unverified-source-field" }
quests[26411] = { id = 26411, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausgebrannt", description = "In Ordnung, nehmt dies und gebt es auf seine Wunden. Wenn die blitzartige Kauterisation ihn nicht in Stücke reißt, sollte er dadurch vollständig heilen.\n\nGlaube ich…", sourceObjective = "Behandelt Flint Erzmantel mit der explosiven Verbundmasse.", completion = "Sieht aus, als hätte es gewirkt. Er sollte jeden Moment zu sich kommen.\n\nIch habe Euch doch gesagt, dass ich ein Großmeister der Alchemie bin!\n\nIch habe noch etwas Harz übrig. Daraus kann ich allerlei wundervolle explodierende Dinge bauen. Was wollt Ihr haben?", sourceObjectiveStatus = "unverified-source-field" }
quests[26412] = { id = 26412, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schatzkiste der Mosh'Ogg", description = "Sagt, habt Ihr von den Ogern gehört? Ich hab' 'nen heißen Tipp von 'nem Typen namens Mok'thardin bekommen, dass sie ein ganz besonderes, magisches Artefakt in ihrer Höhle verstecken. Skeezy weiß das aber besser. Ich rieche Geld aus einer Mulgoremeile Entfernung und ich wette, das Ogerdingsbums ist ein Vermögen wert.\n\nHier ist ein Hinweis: Ich habe gesehen, dass sie eine Kiste in den Ruinen hinter ihrem Hügel bewachen. Habt Ihr Lust, sie für mich zu holen?", sourceObjective = "Holt die Belohnung der Mosh'Ogg aus den Ruinen hinter dem Ogerhügel der Mosh'Ogg.", sourceObjectiveStatus = "unverified-source-field" }
quests[26413] = { id = 26413, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bringt ihn zur Erdenruferin", description = "Er scheint mir immer noch etwas wackelig auf den Beinen zu sein. Sein Kopf muss dröhnen.\n\nAm besten bringt Ihr ihn in den Tempel zur Erdenruferin und schaut, was sie für ihn tun kann.\n\nIch werde noch ein Weilchen hier draußen bleiben und diese Felsklauen \"beobachten\".", sourceObjective = "Bringt Flint Erzmantel zu Erdenruferin Yevaa im Tempel der Erde.", completion = "Die Anwesenheit von Flint Erzmantel ehrt uns. Wie ich gehört habe, befindet sich ein Fragment der Weltensäule im Besitz des Steinvaters.\n\nEs ist von oberster Wichtigkeit, dass wir alle Fragmente wiedererlangen. Die Instabilität zwischen den Welten wird immer stärker. Bald ist sie vielleicht schon so groß, das nicht einmal der mächtige Thrall ihr Einhalt gebieten kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[26414] = { id = 26414, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einen Zander erwischen", description = "Manchmal fische ich zum Spaß. Dann wieder, um zu entspannen, aber manchmal brauche ich eine Herausforderung. Da kommt der verhärtete Zander ins Spiel. Dieser wertvolle Fisch wird nicht als Speise gefangen, sondern wegen der Herausforderung. Ihr werdet den Zander im Sturmwindsee nördlich der Stadt finden. Glaubt Ihr, Ihr seid der Herausforderung gewachsen?", sourceObjective = "Catherine Leland in Sturmwind möchte, dass Ihr ihr 8 verhärtete Zander bringt.", progress = "War die Herausforderung zu viel für Euch?", completion = "Gute Arbeit, {name}. Wie ich sehe, seid Ihr inzwischen ein ziemlich guter Angler. Vielleicht sollte ich Euch bald mit dem Boot mit hinausnehmen, um zu sehen, was Ihr wirklich könnt!", sourceObjectiveStatus = "unverified-source-field" }
quests[26415] = { id = 26415, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Questflag für Logbuch des Kapitäns" }
quests[26416] = { id = 26416, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf in den Dschungel", description = "Mein Kommandant hat mich ausgeschickt, um nach Rekruten Ausschau zu halten, die bei der Verteidigung des Basislagers von Grom'gol im Nördlichen Schlingendorntal helfen. Kennt Ihr das Schlingendorntal? Es ist sehr weit weg... Man muss das Große Meer überqueren, und dann befindet es sich an der südlichen Spitze der Östlichen Königreiche. Ihr passt auf die Beschreibung, die er mir gegeben hat... Seid Ihr daran interessiert, Kalimdor für eine Weile zu verlassen?\n\nWenn ja, sprecht mit meinem Kollegen Bort in Orgrimmar. Er wird Euch behilflich sein, an Bord des Zeppelins zu gehen.\n\nUnd sagt ihm von mir \"Wusel-Dusel\". Er weiß schon, was das bedeutet.", sourceObjective = "Meldet Euch bei Bort in Orgrimmar.", completion = "Hah! Diese Allumpass ist wirklich zu komisch.\n\nOh, stimmt ja, Schlingendorntal. Ihr wollt wirklich dorthin?", sourceObjectiveStatus = "unverified-source-field" }
quests[26417] = { id = 26417, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Nördliche Schlingendorntal: Das Gefallene Reich", description = "Kommandant Aggro'gosh sucht nach ergebenen Hordenmitgliedern, um ihm bei seiner Mission in Grom'gol zu helfen. Wenn Ihr interessiert seid, geht einfach oben auf den Zeppelinturm und besteigt den Zeppelin nach Grom'gol. So einfach ist das!\n\nIm Ernst, das Schlingendorntal ist momentan genau der richtige Aufenthaltsort... Dort gibt es reichlich Action und nicht annähernd so viel Schäden durch den Kataklysmus wie im... sagen wir... Steinkrallengebirge. Ich wünschte, ich könnte mit Euch kommen.", sourceObjective = "Meldet Euch bei Kommandant Aggro'gosh im Basislager Grom'gol im Nördlichen Schlingendorntal.", completion = "Schön, dass Ihr es geschafft habt! Gehen wir an die Arbeit, ja?", sourceObjectiveStatus = "unverified-source-field" }
quests[26418] = { id = 26418, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Panzer von Shadra", description = "Wir müssen noch einen weiteren Teil finden und dann haben wir alles, was wir brauchen.\n\nDer Panzer von Shadra wird von der letzten lebenden Priesterin der Spinnengöttin bewacht, von Qiaga der Bewahrerin. Sie ist auf dem Altar von Zul und wird von anderen fanatischen Zeloten bewacht.\n\nEin Kinderspiel, oder? Steigt die Treppen des Altars hoch und lasst ihren Kopf die Treppen runter rollen. Bringt mir den Panzer und wir können Shadra endlich beschwören.", sourceObjective = "Tötet Qiaga die Bewahrerin und besorgt den Panzer von Shadra.", progress = "Habt Ihr den Panzer?", completion = "Ja... endlich ist es so weit. Shadra wird unser sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[26419] = { id = 26419, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadra, Königin des Giftes", description = "<Der Boden wackelt als der Götze auf den Altar gesetzt wird und der See beginnt zu schäumen! Shadra erscheint!>", sourceObjective = "Tötet Shadra, die Königin des Giftes.", completion = "Ausgezeichnete Arbeit. Ihr habt der Dunklen Fürstin gute Dienste geleistet, {name}.\n\nIhr böses Blut wird unsere Armeen mit einer mächtigen Waffe gegen die verachtenswerte Allianz bieten. Wir werden sie aus diesen Ländern vertreiben.\n\nFür die Horde, versteht sich... und alles dank Eurer Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[26420] = { id = 26420, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach Würmern graben", description = "He da, Angler! Arnold hier sagt, dass Ihr nach einem neuen Angelpunkt sucht und ich glaube, ich kenne genau den richtigen Ort. Nördlich von Sturmwind gibt es ein kleines Fleckchen Erde, das Olivias Teich heißt.\n\nDer Teich wird jedes Jahr mit neuen Kristallbarschen bestückt, aber sie sind schwer zu fangen. Sie beißen nur bei einem bestimmten Köder... Übergroße Regenwürmer. Wenn Ihr das Ufer des Teichs absucht, solltet Ihr ausreichend Würmer finden, die Ihr als Köder benutzen könnt.", sourceObjective = "Findet einen übergroßen Regenwurm in der Nähe von Olivias Teich und benutzt ihn als Köder, um einen Kristallbarsch zu fangen. Kristallbarsche findet man in Olivias Teich, nördlich von Sturmwind.", progress = "Hat der Köder funktioniert?", completion = "Das sind doch mal nette Barsche, {name}. Lasst sie uns braten und probieren, wie sie schmecken!", sourceObjectiveStatus = "unverified-source-field" }
quests[26421] = { id = 26421, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Hochtüftler", description = "Ich weiß nicht, ob Ihr Euch an Mekkadrill erinnert. Nevin teilte mir mit, dass Gedächtnisverluste bei den Überlebenden von Gnomeregan sehr häufig vorkommen.\n\nMekkadrill - oder richtiger: Der Hochtüftler Mekkadrill - ist der Anführer aller Gnome. Er hat es sich zur Gewohnheit gemacht, jeden geretteten Überlebenden persönlich kennenzulernen. Ihr solltet Euch ihm vorstellen. Er befindet sich bei seinem Kriegsrat in dem Zelt mitten in der Stadt.", sourceObjective = "Stellt Euch bei Hochtüftler Mekkadrill in Neu-Tüftlerstadt vor.", completion = "Schön, Euch kennenzulernen, {name}. Wahrscheinlich habt Ihr andere bereits von der Operation: Gnomeregan sprechen gehört. Lasst mich Euch ein wenig darüber erzählen, was geschehen ist und warum wir die Zwergenstadt Eisenschmiede verlassen haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[26422] = { id = 26422, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Hochtüftler", description = "Ich weiß nicht, ob Ihr Euch an Mekkadrill erinnert. Nevin teilte mir mit, dass Gedächtnisverluste bei den Überlebenden von Gnomeregan sehr häufig vorkommen. \n\nMekkadrill - oder richtiger: Der Hochtüftler Mekkadrill - ist der Anführer aller Gnome. Er hat es sich zur Gewohnheit gemacht, jeden geretteten Überlebenden persönlich kennenzulernen. Ihr solltet Euch ihm vorstellen. Er befindet sich bei seinem Kriegsrat in dem Zelt mitten in der Stadt.", sourceObjective = "Stellt Euch bei Hochtüftler Mekkadrill in Neu-Tüftlerstadt vor.", completion = "Schön, Euch kennenzulernen, {name}. Wahrscheinlich habt Ihr andere bereits von der Operation: Gnomeregan sprechen gehört. Lasst mich Euch ein wenig darüber erzählen, was geschehen ist und warum wir die Zwergenstadt Eisenschmiede verlassen haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[26423] = { id = 26423, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Hochtüftler", description = "Ich weiß nicht, ob Ihr Euch an Mekkadrill erinnert. Nevin teilte mir mit, dass Gedächtnisverluste bei den Überlebenden von Gnomeregan sehr häufig vorkommen. \n\nMekkadrill - oder richtiger: Der Hochtüftler Mekkadrill - ist der Anführer aller Gnome. Er hat es sich zur Gewohnheit gemacht, jeden geretteten Überlebenden persönlich kennenzulernen. Ihr solltet Euch ihm vorstellen. Er befindet sich bei seinem Kriegsrat in dem Zelt mitten in der Stadt.", sourceObjective = "Stellt Euch bei Hochtüftler Mekkadrill in Neu-Tüftlerstadt vor.", completion = "Schön, Euch kennenzulernen, {name}. Wahrscheinlich habt Ihr andere bereits von der Operation: Gnomeregan sprechen gehört. Lasst mich Euch ein wenig darüber erzählen, was geschehen ist und warum wir die Zwergenstadt Eisenschmiede verlassen haben.", sourceObjectiveStatus = "unverified-source-field" }
